// TypeScript Version: 4.1

/**
* Returns the expected value of a double Weibull distribution.
*
* ## Notes
*
* -   If `c <= 0`, the function returns `NaN`.
*
* @param c - shape parameter
* @throws `c` must be a positive number
* @returns expected value
*
* @example
* var v = mean( 4.0 );
* // returns 0.0
*
* @example
* var v = mean( 8.0 );
* // returns 0.0
*
* @example
* var v = mean( 1.0 );
* // returns 0.0
*
* @example
* var v = mean( -0.1 );
* // returns NaN
*
* @example
* var v = mean( NaN );
* // returns NaN
*/
declare function mean( c: number ): number;


// EXPORTS //

export = mean;
